/* Minimal single-source harness for the pinned LAGraph 2-rpq API.
 * Input: graph.dat (1-based s p o); larpq.tsv generated by prepare_250k.py.
 * Output: query_id;comma-separated 1-based target IDs.
 * --bench runs warmups additionally emits TIMING rows from one loaded graph/NFA.
 */
#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>
#include <time.h>
#include <string.h>
#include "LAGraph.h"
#include "LAGraphX.h"

static char msg[LAGRAPH_MSG_LEN];
#define CHECK(call) do { int code=(call); if(code != 0) { fprintf(stderr,"%s: %d %s\n",#call,code,msg); exit(1); } } while(0)

int main(int argc, char **argv) {
    bool bench=(argc==8);
    if (argc != 5 && argc != 6 && !bench) { fprintf(stderr,"usage: larpq-smoke graph.dat queries.tsv vertices labels [extended | --bench runs warmups]\n"); return 2; }
    size_t runs=bench?strtoull(argv[6],NULL,10):1, warmups=bench?strtoull(argv[7],NULL,10):0;
    if(bench && (!runs || strcmp(argv[5],"--bench")!=0)) return 2;
    GrB_Index vertices=strtoull(argv[3],NULL,10);
    size_t nl=strtoull(argv[4],NULL,10);
    CHECK(LAGraph_Init(msg));
    const char *threads = getenv("OMP_NUM_THREADS");
    if (threads) CHECK(LAGraph_SetNumThreads(1, atoi(threads), msg));
    LAGraph_Graph *G=calloc(nl,sizeof(*G));
    GrB_Matrix *A=calloc(nl,sizeof(*A));
    bool *inverse=calloc(nl,sizeof(*inverse));
    for(size_t i=0;i<nl;i++) {
        CHECK(GrB_Matrix_new(&A[i],GrB_BOOL,vertices,vertices));
        CHECK(GxB_Matrix_Option_set(A[i],GxB_FORMAT,GxB_BY_ROW));
    }
    FILE *f=fopen(argv[1],"r");
    if(!f) return 2;
    uint64_t s,p,t;
    while(fscanf(f,"%"SCNu64" %"SCNu64" %"SCNu64,&s,&p,&t)==3) {
        if(s<1 || s>vertices || t<1 || t>vertices || p<1 || p>nl) return 2;
        CHECK(GrB_Matrix_setElement_BOOL(A[p-1],true,s-1,t-1));
    }
    fclose(f);
    for(size_t i=0;i<nl;i++) {
        CHECK(LAGraph_New(&G[i],&A[i],LAGraph_ADJACENCY_DIRECTED,msg));
        CHECK(LAGraph_Cached_AT(G[i],msg));
        CHECK(GxB_Matrix_Option_set(G[i]->AT,GxB_FORMAT,GxB_BY_ROW));
    }
    f=fopen(argv[2],"r");
    if(!f) return 2;
    uint64_t id,source,states,mask,ntrans,startmask=1,reverse=0;
    while(1) {
        int read= argc==6
            ? fscanf(f,"%"SCNu64" %"SCNu64" %"SCNu64" %"SCNu64" %"SCNu64" %"SCNu64" %"SCNu64,&id,&source,&states,&startmask,&mask,&reverse,&ntrans)
            : fscanf(f,"%"SCNu64" %"SCNu64" %"SCNu64" %"SCNu64" %"SCNu64,&id,&source,&states,&mask,&ntrans);
        if(read==EOF) break;
        if(read!=(argc==6?7:5)) return 2;
        if(states>63 || source>=vertices) return 2;
        LAGraph_Graph *R=calloc(nl,sizeof(*R));
        for(size_t i=0;i<nl;i++) {
            CHECK(GrB_Matrix_new(&A[i],GrB_BOOL,states,states));
            CHECK(GxB_Matrix_Option_set(A[i],GxB_FORMAT,GxB_BY_ROW));
        }
        for(uint64_t i=0;i<ntrans;i++) {
            if(fscanf(f,"%"SCNu64" %"SCNu64" %"SCNu64,&s,&p,&t)!=3) return 2;
            if(s>=states || t>=states || p>=nl) return 2;
            CHECK(GrB_Matrix_setElement_BOOL(A[p],true,s,t));
        }
        for(size_t i=0;i<nl;i++) {
            CHECK(LAGraph_New(&R[i],&A[i],LAGraph_ADJACENCY_DIRECTED,msg));
            CHECK(LAGraph_Cached_AT(R[i],msg));
            CHECK(GxB_Matrix_Option_set(R[i]->AT,GxB_FORMAT,GxB_BY_ROW));
        }
        GrB_Index QS[64],nqs=0,S=source,QF[64],nqf=0;
        for(GrB_Index i=0;i<states;i++) if(startmask & (UINT64_C(1)<<i)) QS[nqs++]=i;
        for(GrB_Index i=0;i<states;i++) if(mask & (UINT64_C(1)<<i)) QF[nqf++]=i;
        GrB_Vector result=NULL;
        /* R is already reversed for any-con. Invert graph labels only, not R. */
        for(size_t i=0;i<nl;i++) inverse[i]=(reverse!=0);
        for(size_t repetition=0;repetition<warmups+runs;repetition++) {
            if(result) CHECK(GrB_Vector_free(&result));
            struct timespec begin,end;
            if(bench) clock_gettime(CLOCK_MONOTONIC,&begin);
            CHECK(LAGraph_2RegularPathQuery(&result,R,inverse,nl,QS,nqs,QF,nqf,G,&S,1,false,msg));
            if(bench) {
                CHECK(GrB_Vector_wait(result,GrB_MATERIALIZE));
                clock_gettime(CLOCK_MONOTONIC,&end);
                GrB_Index count=0;CHECK(GrB_Vector_nvals(&count,result));
                if(repetition>=warmups) printf("TIMING;%"PRIu64";%zu;%.9f;%"PRIu64"\n",id,repetition-warmups,
                    (end.tv_sec-begin.tv_sec)*1000.0+(end.tv_nsec-begin.tv_nsec)/1e6,(uint64_t)count);
            }
        }
        GrB_Index n=0;
        CHECK(GrB_Vector_nvals(&n,result));
        GrB_Index *indices=calloc(n+1,sizeof(*indices));
        bool *values=calloc(n+1,sizeof(*values));
        CHECK(GrB_Vector_extractTuples_BOOL(indices,values,&n,result));
        printf("%"PRIu64";",id);
        bool first=true;
        for(GrB_Index i=0;i<n;i++) if(values[i]) {
            printf("%s%"PRIu64,first?"":",",(uint64_t)indices[i]+1); first=false;
        }
        printf("\n");
        free(indices); free(values); GrB_Vector_free(&result);
        for(size_t i=0;i<nl;i++) CHECK(LAGraph_Delete(&R[i],msg));
        free(R);
    }
    fclose(f);
    for(size_t i=0;i<nl;i++) CHECK(LAGraph_Delete(&G[i],msg));
    free(G); free(A); free(inverse);
    CHECK(LAGraph_Finalize(msg));
    return 0;
}
